Here's the code I used, with the device on and in charge mode. Your device may have a different vid &| pid 
``` rust
use rusb::{Context, DeviceHandle, GlobalContext};
use std::time::Duration;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let _ctx = Context::new()?;

    let vid = 0x1410;
    let pid = 0xb010;

    let handle: DeviceHandle<GlobalContext> =
        rusb::open_device_with_vid_pid(vid, pid).ok_or("Device 1410:b010 not found")?;

    if handle.kernel_driver_active(0).unwrap_or(false) {
        match handle.detach_kernel_driver(0) {
            Ok(_) => {}
            Err(e) => eprintln!("Warning: failed to detach kernel driver: {}", e),
        }
    }

    handle.claim_interface(0)?;

    // Prepare 130 zero bytes
    let data = vec![0u8; 130];

    let timeout = Duration::from_secs(2);
    let transferred = handle.write_bulk(0x01, &data, timeout)?;

    println!("Sent {} bytes to endpoint 0x01", transferred);

    let _ = handle.release_interface(0);

    Ok(())
}
